from textual.app import ComposeResult
from pathlib import Path
from textual.containers import Container
from textual.widgets import Tree, TextArea
from textual.app import App


class DirectoryApp(App):
    CSS = """
    Screen {
        layout: horizontal;
    }

    #main {
        layout: horizontal;
        width: 100%;
        height: 100%;
    }

    #tree_pane {
        width: 30%;
        border: solid $accent;
    }

    #text_pane {
        width: 70%;
        border: solid $accent;
    }
    """

    BINDINGS = [("q", "quit", "Quit")]

    def compose(self) -> ComposeResult:
        with Container(id="main"):
            yield Tree(".", id="tree_pane")
            yield TextArea(id="text_pane")

    def on_mount(self) -> None:
        tree = self.query_one(Tree)
        self.load_directory(tree.root, Path("."))

    def load_directory(self, node, path: Path) -> None:
        try:
            for item in sorted(path.iterdir()):
                if item.name.startswith('.'):
                    continue
                if item.is_dir():
                    sub_node = node.add(f"📁 {item.name}")
                    self.load_directory(sub_node, item)
                else:
                    node.add(f"📄 {item.name}")
        except (PermissionError, OSError):
            pass


if __name__ == "__main__":
    app = DirectoryApp()
    app.run()

